mapper.select:
SELECT , m.material_name AS materialName, w.node_name AS warehouseName, COALESCE( (SELECT SUM(package_num) FROM spd_label WHERE material_id = sl.material_id AND warehouse_id = sl.warehouse_id AND del_flag = 0 AND label_status = 1), 0 ) + COALESCE( (SELECT SUM(remaining_num) FROM spd_bulk_material WHERE material_id = sl.material_id AND warehouse_id = sl.warehouse_id AND del_flag = 0), 0 ) AS currentStock, CASE WHEN COALESCE((SELECT SUM(package_num) FROM spd_label WHERE material_id = sl.material_id AND warehouse_id = sl.warehouse_id AND del_flag = 0 AND label_status = 1), 0) + COALESCE((SELECT SUM(remaining_num) FROM spd_bulk_material WHERE material_id = sl.material_id AND warehouse_id = sl.warehouse_id AND del_flag = 0), 0) < sl.min_stock THEN 2 WHEN sl.warning_stock IS NOT NULL AND COALESCE((SELECT SUM(package_num) FROM spd_label WHERE material_id = sl.material_id AND warehouse_id = sl.warehouse_id AND del_flag = 0 AND label_status = 1), 0) + COALESCE((SELECT SUM(remaining_num) FROM spd_bulk_material WHERE material_id = sl.material_id AND warehouse_id = sl.warehouse_id AND del_flag = 0), 0) < sl.warning_stock THEN 1 WHEN COALESCE((SELECT SUM(package_num) FROM spd_label WHERE material_id = sl.material_id AND warehouse_id = sl.warehouse_id AND del_flag = 0 AND label_status = 1), 0) + COALESCE((SELECT SUM(remaining_num) FROM spd_bulk_material WHERE material_id = sl.material_id AND warehouse_id = sl.warehouse_id AND del_flag = 0), 0) > sl.max_stock THEN 3 ELSE 0 END AS stockStatus FROM spd_stock_limit sl LEFT JOIN spd_material m ON sl.material_id = m.material_id LEFT JOIN spd_org_node w ON sl.warehouse_id = w.node_id WHERE sl.del_flag = #{delFlag}
AND m.material_name LIKE CONCAT('%', #{query.materialName}, '%')
AND sl.warehouse_id = #{query.warehouseId}
HAVING stockStatus = #{query.stockStatus}
ORDER BY sl.create_time DESC
